// Extract full text from Google Doc
const items = $input.all();
const outputItems = [];

for (const item of items) {
  const text = item.json.text || item.json.content || '';

  // Clean and prepare text
  const cleanText = text.trim();

  outputItems.push({
    json: {
      fullText: cleanText,
      documentId: item.json.documentId,
      title: item.json.title || 'Untitled Document',
      textLength: cleanText.length,
      wordCount: cleanText.split(/\s+/).length
    }
  });
}

return outputItems;

// Create initial chunks for AI analysis
const items = $input.all();
const outputItems = [];

for (const item of items) {
  const fullText = item.json.fullText;
  const chunkSize = 1500; // Larger initial chunks for AI to analyze
  const overlap = 300;

  const chunks = [];

  for (let i = 0; i < fullText.length; i += (chunkSize - overlap)) {
    const start = i;
    const end = Math.min(i + chunkSize, fullText.length);
    const chunkText = fullText.substring(start, end);

    chunks.push({
      text: chunkText,
      start: start,
      end: end,
      chunkNumber: chunks.length + 1
    });

    // Stop if we've reached the end
    if (end >= fullText.length) break;
  }

  outputItems.push({
    json: {
      fullText: fullText,
      documentId: item.json.documentId,
      documentTitle: item.json.title,
      totalChunks: chunks.length,
      chunks: chunks
    }
  });
}

return outputItems;

// Parse AI response and create final chunks
const items = $input.all();
const outputItems = [];

for (const item of items) {
  let aiResponse;

  try {
    // The OpenAI node returns the message content directly
    // It could be in item.json.message or item.json directly
    let content = '';

    if (typeof item.json === 'string') {
      // If the entire response is a string
      content = item.json;
    } else if (item.json.message) {
      // If it's in a message property
      content = item.json.message;
    } else if (item.json.content) {
      // If it's in a content property
      content = item.json.content;
    } else if (item.json.choices && item.json.choices[0]) {
      // Standard OpenAI API format (fallback)
      content = item.json.choices[0].message.content;
    } else {
      // Try to stringify and parse the entire object
      content = JSON.stringify(item.json);
    }

    // Remove markdown code blocks if present
    content = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

    // Parse the JSON content
    aiResponse = JSON.parse(content);

    // Validate structure
    if (!aiResponse.refinedChunks || !Array.isArray(aiResponse.refinedChunks)) {
      throw new Error('Invalid response structure from AI');
    }

    // Get document metadata from previous node
    const docData = $('Break Into Initial Chunks').first().json;

    // Create output items for each refined chunk
    for (const chunk of aiResponse.refinedChunks) {
      outputItems.push({
        json: {
          pageContent: chunk.text,
          metadata: {
            chunkId: chunk.chunkId,
            totalChunks: aiResponse.totalChunks,
            topic: chunk.topic,
            importance: chunk.importance,
            keywords: chunk.keywords || [],
            documentId: docData.documentId,
            documentTitle: docData.documentTitle,
            documentSummary: aiResponse.documentSummary,
            chunkingMethod: 'agentic-ai-refined',
            timestamp: new Date().toISOString()
          }
        }
      });
    }

  } catch (e) {
    // Fallback: use the initial chunks if AI parsing fails
    console.error('AI parsing failed:', e.message);
    console.error('Raw item.json:', JSON.stringify(item.json, null, 2));

    const docData = $('Break Into Initial Chunks').first().json;

    for (let i = 0; i < docData.chunks.length; i++) {
      const chunk = docData.chunks[i];
      outputItems.push({
        json: {
          pageContent: chunk.text,
          metadata: {
            chunkId: i + 1,
            totalChunks: docData.totalChunks,
            topic: 'Fallback chunk ' + (i + 1),
            importance: 5,
            keywords: [],
            documentId: docData.documentId,
            documentTitle: docData.documentTitle,
            chunkingMethod: 'fallback-initial',
            error: e.message,
            rawResponse: JSON.stringify(item.json),
            timestamp: new Date().toISOString()
          }
        }
      });
    }
  }
}

return outputItems;
